import{c as e,Q as a,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"可執行計劃書 — 將 Prompt 研究發現套用到 cc-workspace Harness","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/archive/2026-06-03-prompt-harness-action-plan.md","filePath":"research/reports/archive/2026-06-03-prompt-harness-action-plan.md","lastUpdated":1780842316000}'),s={name:"research/reports/archive/2026-06-03-prompt-harness-action-plan.md"};function d(n,t,i,c,l,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="可執行計劃書-—-將-prompt-研究發現套用到-cc-workspace-harness" tabindex="-1">可執行計劃書 — 將 Prompt 研究發現套用到 cc-workspace Harness <a class="header-anchor" href="#可執行計劃書-—-將-prompt-研究發現套用到-cc-workspace-harness" aria-label="Permalink to &quot;可執行計劃書 — 將 Prompt 研究發現套用到 cc-workspace Harness&quot;">​</a></h1><p><strong>日期</strong>：2026-06-03 | <strong>Branch</strong>：<code>feature/prompt-caching-engineering-research</code><strong>對應研究報告</strong>：<code>2026-06-03-prompt-caching-management-engineering.md</code><strong>研究方法</strong>：平行 researcher subagents fan-out（模擬 overnight-research 搜尋階段 + research-hub 信度分層 + autoresearch 缺口收斂方法論），非直接呼叫三 skill runner。 <strong>Target（釘死假設）</strong>：把三主題發現套用到本 cc-workspace harness（CLAUDE.md 為 stable-prefix cache、<code>context-management.md</code> 已有 caching 規則、4 auto-load 規則）。本計劃為<strong>提案</strong>，破壞性 APPLY 前須 gate 使用者。</p><hr><h2 id="_0-現況基線-改前先讀-§r8" tabindex="-1">0. 現況基線（改前先讀，§R8） <a class="header-anchor" href="#_0-現況基線-改前先讀-§r8" aria-label="Permalink to &quot;0. 現況基線（改前先讀，§R8）&quot;">​</a></h2><p>本 harness 已落地的 prompt 工程實踐：</p><table tabindex="0"><thead><tr><th>已有</th><th>位置</th><th>對應報告章節</th></tr></thead><tbody><tr><td>CLAUDE.md = 穩定前綴、放最前不動</td><td>context-management.md §Static First</td><td>A.4 四層結構</td></tr><tr><td>Mid-session 禁切 model/tool/CLAUDE.md</td><td>context-management.md</td><td>A.4 cache 失效控制</td></tr><tr><td>NLAH（context 放 HEAD/TAIL）</td><td>context-management.md</td><td>C.3 lost-in-the-middle</td></tr><tr><td>Compact hint（保留前綴語意）</td><td>context-management.md</td><td>A.4 compact 須同前綴</td></tr><tr><td>Token budget（4k/task, 30k/session）</td><td>context-management.md §R6</td><td>—</td></tr><tr><td>正向指令優先於禁止</td><td>output-discipline.md</td><td>C.1 positive&gt;negative 🟢</td></tr><tr><td>Tests Verify Intent</td><td>core.md §R9</td><td>C.4 eval-driven</td></tr><tr><td>auto-load byte cap（canonical）</td><td>core.md §Framework Integrity</td><td>A.1 token 經濟</td></tr></tbody></table><p><strong>結論</strong>：本 harness 在 caching「穩定前綴」與 engineering「正向指令」上已對齊官方一手。<strong>缺口</strong>集中在三處：① cache 可觀測性（無 hit-rate 監控）② cross-provider / TTL 決策（規則未提）③ prompt-as-code 版本治理（auto-load 規則本身未當 prompt artifact 做 eval-driven 版控）。</p><hr><h2 id="_1-可執行步驟-按-roi-排序-每步可機械驗證" tabindex="-1">1. 可執行步驟（按 ROI 排序，每步可機械驗證） <a class="header-anchor" href="#_1-可執行步驟-按-roi-排序-每步可機械驗證" aria-label="Permalink to &quot;1. 可執行步驟（按 ROI 排序，每步可機械驗證）&quot;">​</a></h2><h3 id="step-1-—-context-management-md-補「cache-可觀測性」段-高-roi-低風險" tabindex="-1">Step 1 — context-management.md 補「Cache 可觀測性」段（高 ROI，低風險） <a class="header-anchor" href="#step-1-—-context-management-md-補「cache-可觀測性」段-高-roi-低風險" aria-label="Permalink to &quot;Step 1 — context-management.md 補「Cache 可觀測性」段（高 ROI，低風險）&quot;">​</a></h3><p><strong>動作</strong>：在 <code>context-management.md</code> §監控 區塊新增 cache 健康指標規則。</p><p><strong>具體 edit</strong>（提案內容，APPLY 前 gate）：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Cache 健康指標（agentic 生產紅線）</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> `cache_hit_rate = cache_read_input_tokens / input_tokens`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">；長跑 session 應 &gt; 0.7。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 觸發 incident：hit_rate 驟降 → 先查是否 mid-session 切了 model/tool/CLAUDE.md（A.4 四大破快取源）。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 動態資訊（時間戳/檔變更）一律經 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`&lt;system-reminder&gt;`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 注入 messages，</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**不寫進 CLAUDE.md 前綴**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">。</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Agentic 長任務（工具迴圈 &gt;5min）→ 啟用 1h TTL（</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`ENABLE_PROMPT_CACHING_1H=1`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">），代價 2× 寫入費但避免 mid-loop cache miss。</span></span></code></pre></div><p><strong>驗證</strong>：<code>grep -c &quot;cache_hit_rate&quot; .claude/rules/context-management.md</code> ≥ 1；<code>bash scripts/healthcheck.sh</code> FAIL=0；<code>wc -c</code> 確認 auto-load byte 仍 &lt; 18,000 上限。 <strong>風險</strong>：增加 auto-load byte。先量增量 <code>wc -c</code> 再決定是否納入 auto-load 或改 on-demand。</p><h3 id="step-2-—-新增-on-demand-規則-prompt-lifecycle-md-中-roi-零-auto-load-成本" tabindex="-1">Step 2 — 新增 on-demand 規則 <code>prompt-lifecycle.md</code>（中 ROI，零 auto-load 成本） <a class="header-anchor" href="#step-2-—-新增-on-demand-規則-prompt-lifecycle-md-中-roi-零-auto-load-成本" aria-label="Permalink to &quot;Step 2 — 新增 on-demand 規則 `prompt-lifecycle.md`（中 ROI，零 auto-load 成本）&quot;">​</a></h3><p><strong>動作</strong>：建 path-scoped on-demand 規則檔（編輯 <code>.claude/rules/</code>、<code>CLAUDE.md</code>、<code>research/prompts/</code> 時觸發），承載「不夠高頻、不該佔 auto-load」的完整知識：cross-provider 決策表、cross-model 遷移 re-express 原則、structured-output 陷阱、eval-driven prompt 迭代。</p><p><strong>理由</strong>：報告 Section A.1/B.4/C.2 是「需要時查」而非「每 session 載入」→ on-demand 是正確 NLAH placement（避免無謂 auto-load byte 膨脹，符合 Framework Integrity）。 <strong>驗證</strong>：檔案存在、有 frontmatter schema、<code>README.md</code> Path-scoped 表新增一列；healthcheck PASS。</p><h3 id="step-3-—-prompt-as-code-把-auto-load-規則當-prompt-artifact-做-eval-driven-版控-高-roi-呼應既有-autoload-evolution" tabindex="-1">Step 3 — prompt-as-code：把 auto-load 規則當 prompt artifact 做 eval-driven 版控（高 ROI，呼應既有 autoload-evolution） <a class="header-anchor" href="#step-3-—-prompt-as-code-把-auto-load-規則當-prompt-artifact-做-eval-driven-版控-高-roi-呼應既有-autoload-evolution" aria-label="Permalink to &quot;Step 3 — prompt-as-code：把 auto-load 規則當 prompt artifact 做 eval-driven 版控（高 ROI，呼應既有 autoload-evolution）&quot;">​</a></h3><p><strong>動作</strong>：本 harness 已有 <code>/autoload-evolution</code> 閉環 + Falsifiable Prediction 機制（見 MEMORY.md）。將報告 C.4「Better Prompts Hurt」+ B.1 prompt-as-code 整合進該閉環的驗收標準：</p><ul><li>每次改 auto-load 規則 → 必附 falsifiable prediction（已有慣例）<strong>+ 明確 eval 條件</strong>（R1–R12 behavioral 存活、healthcheck FAIL=0、byte cap）。</li><li>規則變更走 feature branch + PR（已有），等同 prompt registry 的 staged deployment（B.1）。 <strong>驗證</strong>：下次 <code>/autoload-evolution</code> cycle 套用此標準；git log 顯示規則變更皆經 PR。 <strong>現況</strong>：本 harness 已 80% 符合（Falsifiable Prediction + PR 流程）— 此步是「形式化既有實踐」，非新建。</li></ul><h3 id="step-4-—-research-prompts-加-cross-model-遷移備註-低-roi-低風險" tabindex="-1">Step 4 — research/prompts/ 加 cross-model 遷移備註（低 ROI，低風險） <a class="header-anchor" href="#step-4-—-research-prompts-加-cross-model-遷移備註-低-roi-低風險" aria-label="Permalink to &quot;Step 4 — research/prompts/ 加 cross-model 遷移備註（低 ROI，低風險）&quot;">​</a></h3><p><strong>動作</strong>：本 repo 有 <code>research/prompts/</code> 9 個 prompt 檔（agent-orchestration、rule-engineering 等）。在 <code>research/prompts/INDEX.md</code> 加一段「模型遷移注意」：re-express ≠ translate、Claude 偏 XML、hardest-cases-first、prompt 不可跨 generation 直接移植（C.1 / B.4）。 <strong>驗證</strong>：<code>grep -i &quot;re-express\\|cross-model\\|遷移&quot; research/prompts/INDEX.md</code> ≥ 1。</p><h3 id="step-5-—-注入防禦對接既有-subagent-strategy-md-中-roi" tabindex="-1">Step 5 — 注入防禦對接既有 subagent-strategy.md（中 ROI） <a class="header-anchor" href="#step-5-—-注入防禦對接既有-subagent-strategy-md-中-roi" aria-label="Permalink to &quot;Step 5 — 注入防禦對接既有 subagent-strategy.md（中 ROI）&quot;">​</a></h3><p><strong>動作</strong>：<code>subagent-strategy.md</code> 已有 <code>&lt;untrusted_objective&gt;</code> 包裹規則（Agent Input Security）。在該段補一行指向報告 B.3：indirect injection 經 RAG/外部內容擴大攻擊面，PostToolUse 外部資料同樣須包裹 + allowlist 心智模型（InstructDetector 的 API-only 等效：把外部內容當 data 不當 instruction）。 <strong>驗證</strong>：<code>grep -i &quot;indirect\\|injection\\|untrusted&quot; .claude/rules/subagent-strategy.md</code> 命中既有 + 新增。</p><hr><h2 id="_2-不做的事-§r2-r3-—-避免過度工程" tabindex="-1">2. 不做的事（§R2/R3 — 避免過度工程） <a class="header-anchor" href="#_2-不做的事-§r2-r3-—-避免過度工程" aria-label="Permalink to &quot;2. 不做的事（§R2/R3 — 避免過度工程）&quot;">​</a></h2><ul><li>❌ 不引入 Langfuse/Braintrust 等外部 prompt registry：本 harness 用 Git + PR + autoload-evolution 已是輕量 prompt-as-code，引入 SaaS 是過度工程。</li><li>❌ 不建 cross-provider 抽象層：報告 B.4 反模式明確 — model-specific 優於 generic。本 harness 鎖定 Claude，無多 provider 需求。</li><li>❌ 不為 cache 監控寫自動化 daemon：cache_hit_rate 是手動 <code>/usage</code> 可查的健康信號，daemon 是 speculative。</li></ul><hr><h2 id="_3-落地順序與-gate-點" tabindex="-1">3. 落地順序與 gate 點 <a class="header-anchor" href="#_3-落地順序與-gate-點" aria-label="Permalink to &quot;3. 落地順序與 gate 點&quot;">​</a></h2><table tabindex="0"><thead><tr><th>順序</th><th>Step</th><th>風險</th><th>Gate</th></tr></thead><tbody><tr><td>1</td><td>Step 1（cache 可觀測性）</td><td>增 byte</td><td>APPLY 前確認 byte 增量</td></tr><tr><td>2</td><td>Step 2（on-demand 新規則）</td><td>低</td><td>確認 schema + README</td></tr><tr><td>3</td><td>Step 5（注入防禦對接）</td><td>低</td><td>grep 驗證</td></tr><tr><td>4</td><td>Step 4（prompts INDEX 備註）</td><td>極低</td><td>grep 驗證</td></tr><tr><td>5</td><td>Step 3（prompt-as-code 形式化）</td><td>流程改變</td><td>下次 autoload-evolution cycle</td></tr></tbody></table><p><strong>所有 Step 走 <code>/autoload-evolution</code> 閉環：≤1 規則/cycle、≤50 行 diff、eval 回歸 ≥5pp → <code>git revert</code></strong>（本 harness 既有約束，不另立）。</p><hr><h2 id="_4-驗收條件-r4-機械可驗" tabindex="-1">4. 驗收條件（R4，機械可驗） <a class="header-anchor" href="#_4-驗收條件-r4-機械可驗" aria-label="Permalink to &quot;4. 驗收條件（R4，機械可驗）&quot;">​</a></h2><ul><li>[ ] 本計劃書存在於 <code>research/reports/</code>，含 ≥5 具體步驟（file + edit + verify 三要素）✅</li><li>[ ] 每步有可機械驗證的 verify 指令（grep / wc / healthcheck）✅</li><li>[ ] 計劃明確區分「做 / 不做」並給理由（§R2/R3）✅</li><li>[ ] 對接既有 harness 機制（autoload-evolution / subagent-strategy / context-management）而非另起爐灶 ✅</li><li>[ ] 落地時：每 Step APPLY 後 <code>bash scripts/healthcheck.sh</code> FAIL=0 且 auto-load byte &lt; 18,000</li></ul><hr><h2 id="_5-一句話總結" tabindex="-1">5. 一句話總結 <a class="header-anchor" href="#_5-一句話總結" aria-label="Permalink to &quot;5. 一句話總結&quot;">​</a></h2><p>本 harness 在「穩定前綴 + 正向指令」已對齊 2026 官方一手；最高 ROI 的三個動作是 <strong>① 加 cache_hit_rate 可觀測性 ② 把 cross-provider/遷移知識放 on-demand 規則（零 auto-load 成本）③ 把 auto-load 規則正式當 eval-driven prompt artifact 版控</strong>（既有 autoload-evolution 已 80% 達成）。其餘外部工具與抽象層均為過度工程，明確不做。</p>',37)])])}const g=e(s,[["render",d]]);export{m as __pageData,g as default};
